create database if not exists DTP character set utf8mb4 collate utf8mb4_general_ci;
use DTP;
create table ACC_RULE (ID integer not null auto_increment, CAT varchar(255), IMPACT varchar(128), LABEL varchar(255), NAME varchar(2048), REFERENCE_INFO varchar(1024), TAGS varchar(1024), UUID varchar(36) not null, primary key (ID)) engine=InnoDB;
