SET @SQL = CASE WHEN VERSION() REGEXP '^[6-9]' OR VERSION() REGEXP '^[0-9]{2,}' OR VERSION() REGEXP '^5\.[7-9]' OR VERSION() REGEXP '^5\.[0-9]{2,}' OR ( VERSION() LIKE '5.6.%' AND NOT VERSION() REGEXP '^5\.6\.[0-3]([^0-9].*)?$' ) THEN 'ALTER TABLE UT_FINDING_DETAIL MODIFY COLUMN START_DATE DATETIME(3) NULL' ELSE 'SELECT 1' END;
PREPARE STMT FROM @SQL;
EXECUTE STMT;
DEALLOCATE PREPARE STMT;
SET @SQL = NULL;
